sp_widget.css:
.admin-dashboard {
  padding: 30px;
  max-width: 1100px;
  margin: auto;
}

.admin-dashboard h2 {
  font-weight: 700;
}

.subtitle {
  margin-bottom: 30px;
}

.dashboard-card {
  background: #ffffff;
  padding: 25px;
  margin-bottom: 20px;
  text-align: center;
  border-radius: 8px;
  box-shadow: 0 2px 8px rgba(0,0,0,0.10);
}

.dashboard-card h2 {
  font-size: 36px;
  margin-bottom: 0;
}

.back-home {
  margin-top: 25px;
}

sp_widget.script:
(function() {

    // =====================================================
    // ADMIN AUTHORIZATION
    // =====================================================

    data.authorized =
        gs.hasRole('x_1958892_smart_0.parking_admin');

    if (!data.authorized) {

        data.error =
            'You are not authorized to access the Admin Dashboard.';

        return;
    }


    // =====================================================
    // INITIAL VALUES
    // =====================================================

    data.totalSlots = 0;
    data.availableSlots = 0;
    data.reservedSlots = 0;

    data.totalBookings = 0;
    data.confirmedBookings = 0;
    data.completedBookings = 0;
    data.cancelledBookings = 0;
    data.expiredBookings = 0;


    // =====================================================
    // TOTAL PARKING SLOTS
    // =====================================================

    var totalSlots = new GlideAggregate(
        'x_1958892_smart_0_parking_slot'
    );

    totalSlots.addAggregate('COUNT');
    totalSlots.query();

    if (totalSlots.next()) {

        data.totalSlots =
            totalSlots.getAggregate('COUNT');
    }


    // =====================================================
    // AVAILABLE PARKING SLOTS
    // =====================================================

    var availableSlots = new GlideAggregate(
        'x_1958892_smart_0_parking_slot'
    );

    availableSlots.addQuery(
        'status',
        'available'
    );

    availableSlots.addAggregate('COUNT');
    availableSlots.query();

    if (availableSlots.next()) {

        data.availableSlots =
            availableSlots.getAggregate('COUNT');
    }


    // =====================================================
    // RESERVED PARKING SLOTS
    // =====================================================

    var reservedSlots = new GlideAggregate(
        'x_1958892_smart_0_parking_slot'
    );

    reservedSlots.addQuery(
        'status',
        'reserved'
    );

    reservedSlots.addAggregate('COUNT');
    reservedSlots.query();

    if (reservedSlots.next()) {

        data.reservedSlots =
            reservedSlots.getAggregate('COUNT');
    }


    // =====================================================
    // TOTAL BOOKINGS
    // =====================================================

    var totalBookings = new GlideAggregate(
        'x_1958892_smart_0_parking_booking'
    );

    totalBookings.addAggregate('COUNT');
    totalBookings.query();

    if (totalBookings.next()) {

        data.totalBookings =
            totalBookings.getAggregate('COUNT');
    }


    // =====================================================
    // COUNT BOOKINGS BY STATUS
    // =====================================================

    function countBookings(status) {

        var ga = new GlideAggregate(
            'x_1958892_smart_0_parking_booking'
        );

        ga.addQuery(
            'booking_status',
            status
        );

        ga.addAggregate('COUNT');
        ga.query();

        if (ga.next()) {

            return ga.getAggregate('COUNT');
        }

        return 0;
    }


    data.confirmedBookings =
        countBookings('confirmed');

    data.completedBookings =
        countBookings('completed');

    data.cancelledBookings =
        countBookings('cancelled');

    data.expiredBookings =
        countBookings('expired');

})();
